// Random Wilcoxon rank statistics: rsignrank and rwilcox.
// Generated by definition (signs chosen by uniforms; ranks sampled without replacement).
// Uniform consumption follows observed R output.

import { unifIndex, unifRand } from "./rng.js";
import { generate } from "./common.js";

/**
 * Random numbers from the distribution of the Wilcoxon signed rank statistic.
 * Equivalent to R's `rsignrank()`.
 *
 * @param nn Number of values to generate.
 * @param n Number of observations in the sample.
 * @returns An array of `nn` values; `NaN` for invalid parameters.
 *
 * @example
 * ```ts
 * setSeed(1);
 * rsignrank(5, 10); // [37, 33, 13, 29, 40]
 * ```
 */
export function rsignrank(nn: number, n: number): number[] {
  return generate(nn, () => {
    if (Number.isNaN(n)) return NaN;
    const k = Math.round(n);
    if (k < 0) return NaN;
    if (k === 0) return 0;
    let r = 0;
    // Choose the sign of rank i with a uniform
    for (let i = 1; i <= k; i++) r += i * Math.floor(unifRand() + 0.5);
    return r;
  });
}

/**
 * Random numbers from the distribution of the Wilcoxon rank sum statistic.
 * Equivalent to R's `rwilcox()`.
 *
 * @param nn Number of values to generate.
 * @param m Number of observations in the first sample.
 * @param n Number of observations in the second sample.
 * @returns An array of `nn` values; `NaN` for invalid parameters.
 *
 * @example
 * ```ts
 * setSeed(1);
 * rwilcox(5, 4, 6); // [7, 5, 12, 17, 10]
 * ```
 */
export function rwilcox(nn: number, m: number, n: number): number[] {
  return generate(nn, () => {
    if (Number.isNaN(m) || Number.isNaN(n)) return NaN;
    const mm = Math.round(m);
    const ny = Math.round(n);
    if (mm < 0 || ny < 0) return NaN;
    if (mm === 0 || ny === 0) return 0;
    // Choose n of 0..m+n-1 without replacement and subtract the minimum n(n-1)/2 from their sum
    let k = mm + ny;
    const x = new Int32Array(k);
    for (let i = 0; i < k; i++) x[i] = i;
    let r = 0;
    for (let i = 0; i < ny; i++) {
      const j = unifIndex(k);
      r += x[j]!;
      x[j] = x[--k]!;
    }
    return r - (ny * (ny - 1)) / 2;
  });
}
